    export default {
        name: 'c_button_img',
        props: {
            configObj: {
                type: Object
            },
            configNme: {
                type: String
            }
        },
        data () {
            return {
                defaults: {},
                configData: {},
				current:0,
				list:[]
            }
        },
        watch: {
            configObj: {
                handler (nVal, oVal) {
                    this.defaults = nVal
                    this.configData = nVal[this.configNme]
					this.getBnt(nVal);
                },
                deep: true
            }
        },
        mounted () {
            this.$nextTick(() => {
                this.defaults = this.configObj;
                this.configData = this.configObj[this.configNme];
				this.getBnt(this.defaults);
            })
        },
        methods: {
			tap(index){
				this.current = index;
				this.configData.tabVal = index;
			},
			getBnt(nVal){
				let obj = [
					{
						url: require('@/assets/images/cart2.png'),
						width: 24,
						height: 24
					},
					{
						url: require('@/assets/images/cart3.png'),
						width: 24,
						height: 24
					}
				]
				if(nVal.bntStyleConfig.typeFrom == 'bnt'){
					this.list = obj
				}else{
					if(nVal.styleConfig.tabVal == 0 || nVal.styleConfig.tabVal == 4){
						this.list = [
							{
								url: require('@/assets/images/cart1.png'),
								width: 42,
								height: 24
							},
							{
								url: require('@/assets/images/cart2.png'),
								width: 24,
								height: 24
							},
							{
								url: require('@/assets/images/cart3.png'),
								width: 24,
								height: 24
							}
						]
					}else{
						this.current = this.current == 2?1:this.current
						this.list = obj
					}
					nVal.bntStyleConfig.tabVal = this.current;
				}
			}
		}
    }
